//! @generated by xtask split-cards.
use super::prelude::*;

/// Thrash (Rare, 1 energy, AnyEnemy: 4 dmg ×2, then exhaust a random Attack
/// from hand AND fold its damage into this Thrash instance's `base_damage`
/// permanently for the rest of combat). Faithful to C# `Thrash.OnPlay`
/// (`MegaCrit.Sts2.Core.Models.Cards/Thrash.cs`): `Attack(4).WithHitCount(2)`,
/// then a random hand-Attack is exhausted and
/// `base.DynamicVars.Damage.BaseValue += exhausted.Damage` — a persistent
/// permanent buff on this Thrash instance. No block. Bead `sts2-rs-3g2m6`;
/// permanent-fold added by faithfulness-audit fix 2026-05-28 (`sts2-rs-1d56i`).
pub(crate) fn play_thrash(state: &mut CombatState, target: Option<CreatureUid>) -> EffectResult {
    let t = target.expect("Thrash: Enemy-targeted");
    // C# `Thrash.Damage.BaseValue` is a `decimal` that accumulates the
    // un-floored `ModifyDamage` of each exhausted attack (`Thrash.cs:67`). Rust
    // keeps the integer part in `base_damage` and the leftover fraction in the
    // `ThrashFoldRem{Num,Den}` vars; deal BOTH hits over the exact rational base
    // so the per-hit modifier (Shrink / Weak / Vulnerable) floors only once —
    // matching C#'s `(int)` truncation at HP application, not a pre-floored base
    // (bead `sts2-rs-thrash-decimal`; CATASTROPHE auto-plays Thrash and shares
    // this root, so the OneTwoPunch replay compounded the per-hit floor error).
    let Some(thrash_uid) = current_card_uid(state) else {
        return EffectResult::Resolved;
    };
    let thrash_idx = thrash_uid.0.get() as usize - 1;
    let base_int = state.cards[thrash_idx].base_damage;
    let rem_num = i64::from(state.cards[thrash_idx].combat_var(VarKey::ThrashFoldRemNum));
    let rem_den = {
        let d = state.cards[thrash_idx].combat_var(VarKey::ThrashFoldRemDen);
        if d <= 0 {
            1i64
        } else {
            i64::from(d)
        }
    };
    let base_num = i64::from(base_int)
        .saturating_mul(rem_den)
        .saturating_add(rem_num);
    let _ = card_effects::deal_damage_player_to_enemy_frac(state, t, base_num, rem_den);
    let _ = card_effects::deal_damage_player_to_enemy_frac(state, t, base_num, rem_den);
    // Exhaust a random Attack from hand (C# `Rng.CombatCardSelection.NextItem`
    // over hand Attacks; the engine drains the single deterministic stream).
    let attack_uids: Vec<sts2_core::CardUid> = state
        .player
        .hand
        .iter()
        .copied()
        .filter(|u| {
            let idx = u.0.get() as usize - 1;
            state.cards[idx].card_type == CardType::Attack
        })
        .collect();
    if !attack_uids.is_empty() {
        let pick = state
            .run_rng
            .combat_card_selection
            .next_int_exclusive(0, attack_uids.len() as i32) as usize;
        let exhausted_uid = attack_uids[pick];
        // Capture the exhausted card's damage BEFORE exhausting (the card
        // index is stable across pile moves — exhaust just relocates the uid).
        // C# folds `Hook.ModifyDamage(BaseValue, …, Move, cardSource: exhausted)`
        // — the exhausted attack's damage modified by the player's PERSISTENT
        // outgoing modifiers (Strength additive, Weak multiplicative; null
        // target → no Vulnerable), NOT its raw printed value. Over successive
        // Thrash plays the Strength contribution compounds, so folding the raw
        // base under-counts (fuzz seed 1936: a 3rd Thrash left an AxeBot at 2 HP
        // that C# killed).
        //
        // VigorPower is the exception: `VigorPower.ModifyDamageAdditive` gates
        // on `cardSource == its latched command's source`. The fold passes the
        // EXHAUSTED card as cardSource, which ≠ the latched Thrash hit, so Vigor
        // contributes 0 to the fold even while live. `player_modified_card_damage`
        // has no cardSource gating, so pre-subtract the player's Vigor: the
        // pipeline is `floor(mul × (base + Strength + Vigor))`, so feeding
        // `base − Vigor` algebraically cancels Vigor's additive while preserving
        // Strength and the Weak multiplier (fuzz seed 4907: a Vigor-4 turn made a
        // naïve fold over-count by 4).
        // C# folds the exhausted card's `CalculatedDamage.Calculate(null)`
        // when it defines that var, else its plain `Damage.BaseValue`
        // (Thrash.cs:54-66). A CalculatedDamage attack (Rend/BodySlam/
        // MindBlast/GoldAxe/PerfectedStrike) carries `base_damage 0` (or a
        // bare CalculationBase) in its spec, so folding the raw `base_damage`
        // dropped the entire scaling term — fuzz seed 5028: an exhausted
        // Rend+1 must fold its CalculationBase 18, doubled across Thrash's two
        // hits (+36), which the raw-0 read lost (KIN ally 40 HP vs C#'s 4).
        let exhausted_base = exhaust_fold_base_damage(state, exhausted_uid);
        let vigor = state.player_power_amount(PowerKind::Vigor);
        let relic_add = thrash_fold_relic_additive(state, exhausted_uid, exhausted_base);
        // C# folds the UN-floored `ModifyDamage` decimal; capture it as an exact
        // rational `(term_num, term_den)` so the sub-integer part is preserved
        // across plays instead of being floored away each fold.
        //
        // `Hook.ModifyDamage` applies the exhausted card's own enchantment
        // first, additive then multiplicative (v0.111.0 Hook.cs:1643-1652,
        // same in v0.107.1): `(base + Sharp) x Corrupted`, and only then the
        // listener additives (Strength, the relic term) and multipliers. The
        // Vigor cancel and the relic additive therefore sit OUTSIDE the
        // enchant multiplier (seed 2158: a Corrupted Anger+ folded 8, not 12).
        let (ench_add, ench_x100) = {
            let card = &state.cards[exhausted_uid.0.get() as usize - 1];
            (
                sts2_core::enchantment_hooks::enchant_damage_additive_for(
                    card,
                    true,
                    state.game_version,
                ),
                sts2_core::enchantment_hooks::enchant_damage_multiplicative_x100(card, true),
            )
        };
        let enchanted_x100 =
            i64::from(exhausted_base.saturating_add(ench_add)).saturating_mul(i64::from(ench_x100));
        let (term_num, mut term_den) = card_effects::player_modified_card_damage_frac_of(
            state,
            enchanted_x100.saturating_add(i64::from(relic_add - vigor).saturating_mul(100)),
            100,
        );
        // Gigantification is the other modifier the fold must see after the
        // attack, not during it. Thrash's attack latches it, and its
        // `AfterAttack` decrements it before the fold (GigantificationPower.cs).
        // Rust consumes at card-play end, so the fold still sees the stack and
        // composes its ×3. One stack is gone in C# by the fold, so divide the
        // ×3 back out; with more stacks C# keeps tripling (`commandToModify ==
        // null`), so leave it (GH #922).
        if state.player_power_amount(PowerKind::Gigantification) == 1 {
            term_den = term_den.saturating_mul(3);
        }
        // Pen Nib keys on the fold's `cardSource` (the exhausted attack, still
        // in Hand), which the card-less relic `DamageCtx` cannot carry: the
        // listener judged Thrash instead. Swap its factor for the one C# gives
        // the exhausted card (x2 when Thrash is the 9th attack, x1 when it is
        // the marked 10th; seeds 2008 / 2029 / 2103).
        let (pen_num, pen_den) =
            crate::relics::uncommon::pen_nib_fold_rescale(state, exhausted_uid);
        let term_num = term_num.saturating_mul(pen_num);
        term_den = term_den.saturating_mul(pen_den);
        exhaust_hand_card(state, exhausted_uid);
        // Accumulate `rem + term` (rational add). The integer part flows into
        // `base_damage`; the reduced fractional remainder (in [0, 1)) goes back
        // into the ThrashFoldRem vars for the next play of THIS instance.
        let sum_num = rem_num
            .saturating_mul(term_den)
            .saturating_add(term_num.saturating_mul(rem_den));
        let sum_den = rem_den.saturating_mul(term_den).max(1);
        let int_gain = sum_num.div_euclid(sum_den);
        let mut new_rem_num = sum_num.rem_euclid(sum_den);
        let mut new_rem_den = sum_den;
        let g = gcd_i64(new_rem_num, new_rem_den);
        if g > 1 {
            new_rem_num /= g;
            new_rem_den /= g;
        }
        state.cards[thrash_idx].base_damage = state.cards[thrash_idx]
            .base_damage
            .saturating_add(i32::try_from(int_gain).unwrap_or(i32::MAX));
        state.cards[thrash_idx].set_combat_var(
            VarKey::ThrashFoldRemNum,
            i32::try_from(new_rem_num).unwrap_or(0),
        );
        state.cards[thrash_idx].set_combat_var(
            VarKey::ThrashFoldRemDen,
            i32::try_from(new_rem_den).unwrap_or(1),
        );
    }
    EffectResult::Resolved
}

/// The relic additive term of Thrash's fold. The fold's
/// `Hook.ModifyDamage(..., damage, ValueProp.Move, cardModel, null, All, ...)`
/// (decomp Thrash.cs:70) walks every listener with the EXHAUSTED attack as
/// `cardSource`, so a card-keyed relic bonus (StrikeDummy +3 on a Strike,
/// MiniatureCannon on an upgraded attack, MysticLighter on an enchanted one,
/// StrikeDummy.cs:19) is folded in. `player_modified_card_damage_frac` walks
/// only the power listeners and the relic multipliers, so the fold dropped it
/// (an exhausted Pommel Strike under StrikeDummy folded 9 where C# folds 12).
/// None of these relics read the target, which C# passes as null; the player
/// stands in for it. Same call in v0.107.1 and v0.111.0, so both builds fold
/// it (GH #806).
fn thrash_fold_relic_additive(
    state: &CombatState,
    exhausted_uid: sts2_core::CardUid,
    exhausted_base: i32,
) -> i32 {
    let Some(player_uid) = state.player.creature_uid else {
        return 0;
    };
    let idx = exhausted_uid.0.get() as usize - 1;
    let ctx = sts2_core::relic_effects::ModifyDamageCtx {
        dealer: Some(player_uid),
        target: player_uid,
        base_damage: exhausted_base,
        props: ValueProps::MOVE,
        card: Some(state.cards[idx].card_id),
        card_uid: Some(exhausted_uid),
    };
    sts2_core::relic_effects::dispatch_modify_damage_additive(state, &ctx)
}

/// Euclidean GCD for the Thrash decimal-fold remainder reduction. Returns at
/// least 1 so the denominator never collapses to 0. Bead `sts2-rs-thrash-decimal`.
fn gcd_i64(a: i64, b: i64) -> i64 {
    let (mut a, mut b) = (a.abs(), b.abs());
    while b != 0 {
        let t = b;
        b = a % b;
        a = t;
    }
    a.max(1)
}

/// The damage C# `Thrash.OnPlay` folds for an exhausted attack: its
/// `CalculatedDamage.Calculate(null)` when the card defines that var, else
/// its plain `Damage.BaseValue` (the upgrade-aware `base_damage` field).
/// `Calculate(null)` evaluates `CalculationBase + ExtraDamage × multiplier(
/// card, target=null)`; the NULL target zeroes a target-relative multiplier
/// (Rend's debuff count), while self/global multipliers (block, draw size,
/// card-plays, Strike count) compute normally. Cards not enumerated here
/// carry only a plain `Damage` var (or none), so the `base_damage` fallback
/// is exactly C#'s `else` branch — folding identically to the pre-`vl6ci`
/// behaviour, hence no regression for non-scaling exhaust picks. Mirrors the
/// `CalculatedDamageVar` definitions in v0.103.2 (Rend.cs / BodySlam.cs /
/// MindBlast.cs / GoldAxe.cs / PerfectedStrike.cs / AshenStrike.cs). Beads
/// `sts2-rs-vl6ci`, `sts2-rs-thrash-ashen-fold`.
fn exhaust_fold_base_damage(state: &CombatState, uid: sts2_core::CardUid) -> i32 {
    let idx = uid.0.get() as usize - 1;
    let card = &state.cards[idx];
    let upgraded = card.upgraded;
    match card.card_id {
        // CalculationBase 15→18 (v0.111.0: 10→12, Rend.cs:19,40); the
        // `target?.debuffs ?? 0` multiplier is 0 under the null target Thrash
        // passes, so only the base remains — `preview_rend` with no target.
        CardId::Rend => crate::cards::colorless::rend::preview_rend(state, card, None),
        // 0 + 1 × owner block.
        CardId::BodySlam => state.player.block,
        // 0 + 1 × draw-pile size.
        CardId::MindBlast => i32::try_from(state.player.draw.len()).unwrap_or(i32::MAX),
        // 0 + 1 × player card-plays finished this combat. Thrash itself is
        // still in-flight (counted at play-FINISH, after dispatch), so it is
        // not yet included — mirrors `play_gold_axe`'s direct read.
        CardId::GoldAxe => {
            i32::try_from(state.combat_log.player_card_plays_this_combat).unwrap_or(i32::MAX)
        }
        // CalculationBase 6 (no OnUpgrade on base) + (2→3) × Strike-tagged
        // cards across the five live piles. The pick is still in hand at fold
        // time, so it counts itself — matching C# `AllCards`.
        CardId::PerfectedStrike => {
            let strikes: i32 = state
                .player
                .hand
                .iter()
                .chain(state.player.draw.iter())
                .chain(state.player.discard.iter())
                .chain(state.player.exhaust.iter())
                .chain(state.player.play.iter())
                .filter(|u| {
                    let i = u.0.get() as usize - 1;
                    state.cards[i].has_tag(sts2_core::cards::CardTag::Strike)
                })
                .count()
                .try_into()
                .unwrap_or(0);
            let per = if upgraded { 3 } else { 2 };
            card.base_damage + per * strikes
        }
        // CalculationBase 6 + (3→4 upgraded) × Exhaust-pile size. The Exhaust
        // multiplier is a self/global count (not target-relative), so it
        // computes under the null target C# `Thrash` passes — mirror
        // `play_ashen_strike` exactly. The pick is still in HAND at fold time,
        // so it is NOT yet in the exhaust pile (matches C#'s evaluation order).
        // Bead `sts2-rs-thrash-ashen-fold` (CATASTROPHE auto-plays a Thrash that
        // folds AshenStrike; the missing scaling left the enemy 6 HP too high).
        CardId::AshenStrike => {
            let per = if upgraded { 4 } else { 3 };
            let exhaust_count = i32::try_from(state.player.exhaust.len()).unwrap_or(i32::MAX);
            card.base_damage + per * exhaust_count
        }
        // GangUp is a CalculatedDamage card: `CalculationBase(5) + ExtraDamage
        // (5→7) × mult`, where `mult` counts OTHER same-side allies' powered
        // attacks on the target this turn (`GangUp.cs` CanonicalVars). The card
        // is `MultiplayerOnly` and this engine is solo, so `mult` is always 0 —
        // `Calculate(null)` = CalculationBase 5 (matching `play_gang_up`'s flat
        // 5). The card's `base_damage` spec field is 0 (it carries only the
        // CalculationBase var), so the raw fold dropped the entire 5 — seed
        // 3552: Thrash folded GangUp as 0 instead of 5, and the doubled
        // under-count (Stampede auto-played that Thrash for 2 hits) left
        // VineShambler alive at 9 where C# killed it.
        CardId::GangUp => 5,
        // The other `CalculatedDamage` attacks fold `Calculate(null)`: their
        // previews with no target (a target-keyed multiplier — Bully's
        // Vulnerable, Time's Up's Doom — is 0, as under C#'s null). A
        // Supermassive folded only its base 5 where C# folded 5 + 3 × the
        // cards generated this combat (loadout Ironclad 3111 v0.107.1).
        CardId::Bully => crate::cards::ironclad::bully::preview_bully(state, card, None),
        CardId::CrescentSpear => {
            crate::cards::regent::crescent_spear::preview_crescent_spear(state, card, None)
        }
        CardId::Supermassive => {
            crate::cards::regent::supermassive::preview_supermassive(state, card, None)
        }
        CardId::DeathMarch => {
            crate::cards::necrobinder::death_march::preview_death_march(state, card, None)
        }
        CardId::Protector => {
            crate::cards::necrobinder::protector::preview_protector(state, card, None)
        }
        CardId::SoulStorm => {
            crate::cards::necrobinder::soul_storm::preview_soul_storm(state, card, None)
        }
        CardId::Squeeze => crate::cards::necrobinder::squeeze::preview_squeeze(state, card, None),
        CardId::TimesUp => crate::cards::necrobinder::times_up::preview_times_up(state, card, None),
        CardId::Unleash => crate::cards::necrobinder::unleash::preview_unleash(state, card, None),
        CardId::MementoMori => {
            crate::cards::silent::memento_mori::preview_memento_mori(state, card, None)
        }
        CardId::Murder => crate::cards::silent::murder::preview_murder(state, card, None),
        CardId::PreciseCut => {
            crate::cards::silent::precise_cut::preview_precise_cut(state, card, None)
        }
        // Rampage grows its damage on each play. C# stores the growth IN
        // `Damage.BaseValue` (`Rampage.cs:54` `Damage.BaseValue += Increase`),
        // so Thrash folds the GROWN value (Thrash.cs:60 `else` branch reads
        // `Damage.BaseValue`). Rust keeps `base_damage` at the printed 9 and
        // accumulates the per-play bonus in the `RampageDamage` combat var
        // (`play_rampage`: `current_damage + RampageDamage`), so the raw
        // `base_damage` read under-counts a previously-played Rampage by its
        // accumulated growth (seed 3646: a Rampage+ played once was folded as 9
        // instead of 18, leaving the boss 9 HP too high two Thrash plays later).
        CardId::Rampage => card.base_damage + card.combat_var(VarKey::RampageDamage),
        // Osty attacks with only an `OstyDamage` var: Thrash folds its
        // `BaseValue` (Thrash.cs:62-65), which `OnUpgrade` raised
        // (`OstyDamage.UpgradeValueBy`, same in v0.107.1). These cards keep
        // `base_damage` at the printed value and apply the upgrade in their
        // handler (`upgrade()` is `None`), so add the bump here (Bone Shards+
        // folded 9 instead of 12: Ironclad-8019 act3#b2). Poke / Snap carry a
        // spec delta and take the `base_damage` arm.
        CardId::BoneShards | CardId::Fetch => card.base_damage + if upgraded { 3 } else { 0 },
        CardId::Flatten => card.base_damage + if upgraded { 4 } else { 0 },
        CardId::HighFive | CardId::Rattle | CardId::RightHandHand => {
            card.base_damage + if upgraded { 2 } else { 0 }
        }
        CardId::SicEm => card.base_damage + i32::from(upgraded),
        // Plain `Damage` var (or none): fold BaseValue, exactly C#'s `else`.
        _ => card.base_damage,
    }
}

#[must_use]
pub(crate) const fn spec() -> CardSpec {
    CardSpec {
        id: CardId::Thrash,
        name: "THRASH",
        cost: 1,
        card_type: CardType::Attack,
        target_type: TargetType::Enemy,
        rarity: CardRarity::Rare,
        base_damage: 4,
        base_block: 0,
        keywords: CardKeywords::NONE,
        ..CardSpec::base()
    }
}

#[allow(clippy::unnecessary_wraps, dead_code)]
pub(crate) fn upgrade() -> Option<CardUpgradeDelta> {
    Some(CardUpgradeDelta {
        cost: None,
        base_damage: Some(6),
        base_block: None,
        keywords: None,
    })
}
